WITH p AS (SELECT COALESCE(json_extract_string(state,'$.book'),'main') AS book, json_extract_string(state,'$.account') AS acc, CAST(json_extract_string(state,'$.date') AS DATE) AS d, CASE WHEN json_extract_string(state,'$.side')='debit' THEN CAST(json_extract(state,'$.amount') AS BIGINT) ELSE 0 END AS dr, CASE WHEN json_extract_string(state,'$.side')='credit' THEN CAST(json_extract(state,'$.amount') AS BIGINT) ELSE 0 END AS cr FROM objects WHERE object_type = 'posting' AND CAST(json_extract_string(state,'$.date') AS DATE) <= {{period_to}}), t AS (SELECT book, acc, COALESCE(SUM(dr - cr) FILTER (WHERE d < {{year_from}}), 0) AS bo, COALESCE(SUM(dr) FILTER (WHERE d >= {{period_from}}), 0) AS pd, COALESCE(SUM(cr) FILTER (WHERE d >= {{period_from}}), 0) AS pc, COALESCE(SUM(dr) FILTER (WHERE d >= {{year_from}}), 0) AS yd, COALESCE(SUM(cr) FILTER (WHERE d >= {{year_from}}), 0) AS yc FROM p GROUP BY 1, 2) SELECT t.book, json_extract_string(a.state,'$.code') AS code, json_extract_string(a.state,'$.name') AS account, GREATEST(bo, 0) AS opening_debit, GREATEST(-bo, 0) AS opening_credit, pd AS debit, pc AS credit, yd AS ytd_debit, yc AS ytd_credit, GREATEST(bo + yd - yc, 0) AS closing_debit, GREATEST(-(bo + yd - yc), 0) AS closing_credit, a.object_id AS _of FROM t JOIN objects a ON a.object_id = t.acc AND a.object_type = 'account' WHERE bo <> 0 OR yd <> 0 OR yc <> 0 ORDER BY t.book, code
